export class InventoryService {
    readonly store: InventoryStore;
    private readonly now: () => number;

    constructor(store: InventoryStore, now = () => Date.now()) {
        this.store = store;
        this.now = now;
    }

    initialize(warehouseId: string, sku: string, amount: number): StockItem {
        if (this.store.getStock(warehouseId, sku)) {
            throw new Error('Stock already exists');
        }
        return this.store.putStock(createStock(sku, warehouseId, amount, this.now()));
    }

    reserve(input: ReserveInput): Reservation {
        quantity(input.quantity);
        if (!input.reservationId || !input.orderId) {
            throw new Error('Reservation and order identifiers are required');
        }
        const existing = this.store.getReservation(input.reservationId);
        if (existing) {
            if (existing.orderId !== input.orderId || existing.sku !== input.sku || existing.quantity !== input.quantity || existing.warehouseId !== input.warehouseId) {
                throw new Error('Reservation identifier reused with different input');
            }
            return existing;
        }
        const current = this.stock(input.warehouseId, input.sku);
        const timestamp = this.now();
        const next = reserveStock(current, input.quantity, timestamp);
        const reservation: Reservation = {
            id: input.reservationId,
            orderId: input.orderId,
            warehouseId: input.warehouseId,
            sku: input.sku,
            quantity: input.quantity,
            state: 'active',
            createdAt: timestamp,
            updatedAt: timestamp,
        };
        this.store.putStock(next, current.version);
        return this.store.putReservation(reservation);
    }

    release(id: string): Reservation {
        const current = this.reservation(id);
        const timestamp = this.now();
        const nextReservation = changeReservation(current, 'released', timestamp);
        const stock = this.stock(current.warehouseId, current.sku);
        const nextStock = releaseStock(stock, current.quantity, timestamp);
        this.store.putStock(nextStock, stock.version);
        return this.store.putReservation(nextReservation);
    }

    consume(id: string): Reservation {
        const current = this.reservation(id);
        const timestamp = this.now();
        const nextReservation = changeReservation(current, 'consumed', timestamp);
        const stock = this.stock(current.warehouseId, current.sku);
        const nextStock = consumeStock(stock, current.quantity, timestamp);
        this.store.putStock(nextStock, stock.version);
        return this.store.putReservation(nextReservation);
    }

    receive(warehouseId: string, sku: string, amount: number): StockItem {
        const current = this.stock(warehouseId, sku);
        const next = receiveStock(current, amount, this.now());
        return this.store.putStock(next, current.version);
    }

    stock(warehouseId: string, sku: string): StockItem {
        const item = this.store.getStock(warehouseId, sku);
        if (!item) {
            throw new Error('Stock not found');
        }
        return item;
    }

    reservation(id: string): Reservation {
        const value = this.store.getReservation(id);
        if (!value) {
            throw new Error('Reservation not found');
        }
        return value;
    }

    list(warehouseId?: string): StockItem[] {
        return this.store.stockList(warehouseId);
    }

    listReservations(orderId?: string): Reservation[] {
        return this.store.reservationList(orderId);
    }

    transfer(sourceId: string, destinationId: string, sku: string, amount: number): void {
        if (sourceId === destinationId) {
            throw new Error('Transfer warehouses must differ');
        }
        this.store.transaction(isolated => {
            const service = new InventoryService(isolated, this.now);
            const source = service.stock(sourceId, sku);
            const destination = service.stock(destinationId, sku);
            const held = reserveStock(source, amount, this.now());
            isolated.putStock(consumeStock(held, amount, this.now()), source.version);
            isolated.putStock(receiveStock(destination, amount, this.now()), destination.version);
        });
    }
}

