export class AuditService {
    private readonly store: AuditStore;
    private readonly now: () => number;
    private readonly id: () => string;

    constructor(store: AuditStore, id: () => string, now = () => Date.now()) {
        this.store = store;
        this.id = id;
        this.now = now;
    }

    record(action: string, actorId: string, payload: Record<string, unknown>): AuditEntry {
        if (!action.trim() || !actorId.trim()) {
            throw new Error('Audit action and actor are required');
        }
        const entry = safeAudit({
            id: this.id(),
            action,
            actorId,
            payload,
            createdAt: this.now(),
        });
        return this.store.append(entry);
    }

    list(query: AuditQuery = {}): AuditEntry[] {
        if (query.from !== undefined && query.to !== undefined && query.from > query.to) {
            throw new Error('Audit interval is invalid');
        }
        return this.store.all().filter(entry => {
            if (query.action !== undefined && query.action !== entry.action) return false;
            if (query.actorId !== undefined && query.actorId !== entry.actorId) return false;
            if (query.from !== undefined && entry.createdAt < query.from) return false;
            if (query.to !== undefined && entry.createdAt > query.to) return false;
            return true;
        });
    }

    topics(query: AuditQuery = {}): string[] {
        return [...new Set(this.list(query).map(entry => auditTopic(entry.action)))].sort();
    }

    statistics(query: AuditQuery = {}): { count: number; actors: number; actions: Record<string, number> } {
        const entries = this.list(query);
        const actions: Record<string, number> = {};
        for (const entry of entries) {
            actions[entry.action] = (actions[entry.action] ?? 0) + 1;
        }
        return {
            count: entries.length,
            actors: new Set(entries.map(entry => entry.actorId)).size,
            actions,
        };
    }
}

export class EventStore {
    private readonly values: EventRecord[] = [];
    append(event: EventRecord): EventRecord { if (this.values.some(item => item.id === event.id)) throw new Error('Duplicate event'); this.values.push({ ...event, payload: { ...event.payload } }); return event; }
    all(): EventRecord[] { return this.values.map(event => ({ ...event, payload: { ...event.payload } })); }
    topic(topic: string): EventRecord[] { return this.all().filter(event => event.topic === topic); }
    actor(actorId: string): EventRecord[] { return this.all().filter(event => event.actorId === actorId); }
    since(createdAt: number): EventRecord[] { return this.all().filter(event => event.createdAt >= createdAt); }
    count(): number { return this.values.length; }
    latest(): EventRecord | undefined { return this.values[this.values.length - 1]; }
    clear(): void { this.values.length = 0; }
}

export class Money {
    readonly cents: number;
    constructor(cents: number) {
        if (!Number.isInteger(cents)) throw new Error('Money must use integer cents');
        if (cents < 0) throw new Error('Money cannot be negative');
        this.cents = cents;
    }
    static fromMajor(value: number): Money {
        if (!Number.isFinite(value)) throw new Error('Invalid money value');
        return new Money(Math.round(value * 100));
    }
    static fromCents(value: number): Money { return new Money(value); }
    add(other: Money): Money { return new Money(this.cents + other.cents); }
    subtract(other: Money): Money { return new Money(this.cents - other.cents); }
    multiply(count: number): Money { return new Money(Math.round(this.cents * count)); }
    greaterThan(other: Money): boolean { return this.cents > other.cents; }
    greaterThanOrEqual(other: Money): boolean { return this.cents >= other.cents; }
    equals(other: Money): boolean { return this.cents === other.cents; }
    toMajor(): number { return this.cents / 100; }
    toJSON(): { cents: number } { return { cents: this.cents }; }
}

export function pageQuery(input: Record<string, unknown>): PageQuery {
    return {
        offset: input.offset === undefined ? 0 : integerInput(input.offset, 'offset'),
        limit: input.limit === undefined ? 20 : integerInput(input.limit, 'limit', 1, 100),
    };
}

export class DeliveryService {
    private readonly outbox: NotificationOutbox;
    private readonly policy: DeliveryPolicy;
    private readonly now: () => number;

    constructor(outbox: NotificationOutbox, policy: DeliveryPolicy, now = () => Date.now()) {
        if (!Number.isInteger(policy.maxAttempts) || policy.maxAttempts < 1) {
            throw new Error('Delivery attempt limit must be positive');
        }
        if (!Number.isInteger(policy.batchSize) || policy.batchSize < 1 || policy.batchSize > 100) {
            throw new Error('Delivery batch size is invalid');
        }
        if (!Number.isInteger(policy.initialDelay) || policy.initialDelay < 1) {
            throw new Error('Delivery initial delay is invalid');
        }
        if (!Number.isInteger(policy.maximumDelay) || policy.maximumDelay < policy.initialDelay) {
            throw new Error('Delivery maximum delay is invalid');
        }
        this.outbox = outbox;
        this.policy = {...policy};
        this.now = now;
    }

    ready(): OutboxMessage[] {
        return this.outbox.due(this.now(),this.policy.batchSize);
    }

    begin(id: string): OutboxMessage {
        return this.outbox.claim(id,this.now());
    }

    succeed(id: string): DeliveryReceipt {
        const message = this.outbox.complete(id,this.now());
        return {
            messageId:message.id,
            recipient:message.recipient,
            deliveredAt:message.deliveredAt!,
            attempts:message.attempts,
        };
    }

    reject(id: string, reason: string): DeliveryFailure {
        if (!reason.trim()) {
            throw new Error('Delivery failure requires a reason');
        }
        const current = this.outbox.get(id);
        const delay = Math.min(this.policy.maximumDelay,this.policy.initialDelay * 2 ** (current.attempts - 1));
        const failed = this.outbox.fail(id,reason,this.now()+delay,this.policy.maxAttempts);
        return {
            messageId:id,
            reason,
            nextAttemptAt:failed.nextAttemptAt,
            exhausted:failed.state === 'failed',
        };
    }

    receipts(recipient?: string): DeliveryReceipt[] {
        return this.outbox.list('delivered')
            .filter(message=>recipient===undefined || message.recipient===recipient)
            .map(message=>({
                messageId:message.id,
                recipient:message.recipient,
                deliveredAt:message.deliveredAt!,
                attempts:message.attempts,
            }));
    }

    health(): {pending: number; delivering: number; delivered: number; failed: number; exhaustedIds: string[]} {
        return {
            ...this.outbox.counts(),
            exhaustedIds:this.outbox.list('failed').map(message=>message.id).sort(),
        };
    }
}

export class InvoiceService {
    private readonly store: InvoiceStore;
    constructor(store: InvoiceStore) { this.store = store; }
    create(id: string, orderId: string, customerId: string): Invoice { return this.store.save(createInvoice(id, orderId, customerId)); }
    addLine(id: string, description: string, quantity: number, amount: Money): Invoice { const invoice = this.get(id); return this.store.save(addInvoiceLine(invoice, description, quantity, amount)); }
    issue(id: string, issuedAt: number, dueAt: number): Invoice { return this.store.save(issueInvoice(this.get(id), issuedAt, dueAt)); }
    get(id: string): Invoice { const invoice = this.store.get(id); if (!invoice) throw new Error('Invoice not found'); return invoice; }
    total(id: string): Money { return invoiceTotal(this.get(id)); }
    list(status?: Invoice['status']): Invoice[] { return status ? this.store.byStatus(status) : this.store.all(); }
    count(status?: Invoice['status']): number { return this.list(status).length; }
    exportRows(): Array<Record<string, unknown>> { return this.list().map(invoice => ({ id: invoice.id, orderId: invoice.orderId, customerId: invoice.customerId, status: invoice.status, totalCents: invoiceTotal(invoice).cents })); }
}

export function approveSettlement(batch: SettlementBatch, memberId: string, now: number): SettlementBatch {
    if (batch.state !== 'draft' || !memberId) {
        throw new Error('Settlement cannot be approved');
    }
    return {
        ...batch,
        state: 'approved',
        approvedBy: memberId,
        approvedAt: now,
    };
}

export function normalizeMember(input: { id?: string; displayName: string; email: string; role?: Member['role'] }, id: string, joinedAt: number): Member {
    const displayName = input.displayName.trim();
    const email = input.email.trim().toLowerCase();
    if (!displayName || !email.includes('@')) throw new Error('Invalid member');
    return { id, displayName, email, role: input.role ?? 'viewer', active: true, joinedAt };
}

putStock(item: StockItem, expectedVersion?: number): StockItem {
        const key = stockKey(item.warehouseId, item.sku);
        const current = this.stocks.get(key);
        if (expectedVersion !== undefined && current?.version !== expectedVersion) {
            throw new Error('Inventory version conflict');
        }
        this.stocks.set(key, { ...item });
        this.revision += 1;
        return { ...item };
    }

