transfer(sourceId: string, destinationId: string, sku: string, amount: number): void {
        if (sourceId === destinationId) {
            throw new Error('Transfer warehouses must differ');
        }
        this.store.transaction(isolated => {
            const service = new InventoryService(isolated, this.now);
            const source = service.stock(sourceId, sku);
            const destination = service.stock(destinationId, sku);
            const held = reserveStock(source, amount, this.now());
            isolated.putStock(consumeStock(held, amount, this.now()), source.version);
            isolated.putStock(receiveStock(destination, amount, this.now()), destination.version);
        });
    }

export function createTraceStore(storagePath: string, sensitiveValues: string[] = collectSensitiveEnvironment()) {
  const collectedValues = [...new Set([...collectSensitiveEnvironment(), ...sensitiveValues])];
  let operations = Promise.resolve();

  return {
    async append(input: Omit<AgentTraceEvent, "sequence" | "timestamp">) {
      let result: AgentTraceEvent | undefined;
      operations = operations.then(async () => {
        const events = await readTrace(storagePath);
        const event = redactSensitive(
          {
            ...input,
            sequence: (events.at(-1)?.sequence ?? 0) + 1,
            timestamp: new Date().toISOString()
          },
          collectedValues
        ) as AgentTraceEvent;
        await fs.mkdir(path.dirname(storagePath), { recursive: true });
        await fs.appendFile(storagePath, `${JSON.stringify(event)}\n`, "utf8");
        result = event;
      });
      await operations;
      if (!result) throw new Error("Agent trace event was not created");
      return result;
    },
    async list() {
      await operations;
      return readTrace(storagePath);
    }
  };
}

