export function createIdentityMiddleware(options: {
  members: MemberStore;
  projectId?: (request: Request) => string | undefined;
  required?: boolean;
}) {
  return async function identityMiddleware(request: Request, response: Response, next: NextFunction) {
    try {
    const projectId = options.projectId?.(request)
      ?? request.params.projectId
      ?? request.path.match(/\/api\/projects\/([^/]+)/)?.[1];
    const memberId = request.header("x-simplercp-member")?.trim();
    if (memberId) {
      const member = projectId && !["import", "import-zip"].includes(projectId)
        ? await options.members.resolveIdentity(decodeURIComponent(projectId), memberId)
        : await options.members.findIdentity(memberId);
      if (member) {
        request.identity = { projectId: member.projectId, memberId: member.memberId, displayName: member.displayName, role: member.role };
        next();
        return;
      }
    }
    if (options.required) {
      response.status(401).json({ error: "Member identity is required" });
      return;
    }
    next();
    } catch (error) { next(error); }
  };
}

export function resolveWorkspacePath(root: string, relativePath: string) {
  if (isIgnoredPath(relativePath)) {
    throw new Error("Path is excluded from browser access");
  }
  const absoluteRoot = path.resolve(root);
  const candidate = path.resolve(absoluteRoot, relativePath);
  const relative = path.relative(absoluteRoot, candidate);

  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error("Path escapes workspace root");
  }

  return candidate;
}

export function createRoomStore(events: EventLog) {
  const rooms = new Map<string, RoomState>();

  return {
    createRoom(workspaceRoot: string, workspaceName = path.basename(workspaceRoot)) {
      const room: RoomState = {
        id: nanoid(10),
        workspaceName,
        members: [],
        connections: []
      };
      rooms.set(room.id, room);
      events.append({
        type: "room_created",
        roomId: room.id,
        payload: { workspaceName: room.workspaceName }
      });
      return room;
    },
    getRoom(roomId: string) {
      return rooms.get(roomId);
    },
    joinRoom(roomId: string, input: JoinRoomInput) {
      const room = rooms.get(roomId);
      if (!room) {
        throw new Error("Room not found");
      }

      const normalized = normalizeJoinInput(input);
      const now = new Date().toISOString();
      const existing = findExistingMember(room.members, normalized);
      if (existing) {
        existing.name = normalized.name;
        existing.participantId = normalized.participantId;
        existing.profileRole = normalized.profileRole;
        upsertConnection(room, {
          id: normalized.connectionId,
          participantId: existing.participantId,
          roomId,
          online: true,
          lastSeenAt: now
        });
        syncMemberFromConnections(room, existing, now);
        refreshDisplayNames(room);
        events.append({
          type: "member_rejoined",
          roomId,
          memberId: existing.id,
          payload: {
            name: existing.name,
            participantId: existing.participantId,
            connectionId: normalized.connectionId,
            connectionCount: existing.connectionCount
          }
        });
        return existing;
      }

      const member: RoomMember = {
        id: input.memberId ?? nanoid(10),
        participantId: normalized.participantId,
        name: normalized.name,
        displayName: normalized.name,
        online: true,
        lastSeenAt: now,
        connectionCount: 1,
        profileRole: normalized.profileRole
      };
      room.members.push(member);
      upsertConnection(room, {
        id: normalized.connectionId,
        participantId: member.participantId,
        roomId,
        online: true,
        lastSeenAt: now
      });
      refreshDisplayNames(room);
      events.append({
        type: "member_joined",
        roomId,
        memberId: member.id,
        payload: {
          name: member.name,
          participantId: member.participantId,
          connectionId: normalized.connectionId
        }
      });
      return member;
    },
    markOnline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = true;
      member.lastSeenAt = now.toISOString();
      if (!wasOnline) {
        events.append({
          type: "member_online",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOnline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = true;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (!wasOnline && member.online) {
        events.append({
          type: "member_online",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    markOffline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = false;
      member.lastSeenAt = now.toISOString();
      if (wasOnline) {
        events.append({
          type: "member_offline",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOffline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = false;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (wasOnline && !member.online) {
        events.append({
          type: "member_offline",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    cleanupStaleMembers(roomId: string, now = new Date(), ttlMs = 120_000) {
      const room = findRoom(rooms, roomId);

      const before = room.members.length;
      room.connections = room.connections.filter((connection) => {
        if (connection.online) return true;
        return now.getTime() - new Date(connection.lastSeenAt).getTime() <= ttlMs;
      });
      for (const member of room.members) {
        syncMemberFromConnections(room, member, member.lastSeenAt);
      }
      room.members = room.members.filter((member) => {
        if (member.online) return true;
        return now.getTime() - new Date(member.lastSeenAt).getTime() <= ttlMs;
      });

      if (room.members.length !== before) {
        events.append({
          type: "member_removed",
          roomId,
          payload: { removed: before - room.members.length }
        });
      }

      return room.members;
    },
    updatePresence(
      roomId: string,
      memberId: string,
      patch: Pick<RoomMember, "currentFile"> & { connectionId?: string }
    ) {
      const room = findRoom(rooms, roomId);
      const member = room.members.find(
        (candidate) => candidate.id === memberId
      );
      if (!member) {
        throw new Error("Member not found");
      }

      if (patch.connectionId) {
        const connection = room.connections.find(
          (candidate) => candidate.id === patch.connectionId
        );
        if (connection) {
          connection.currentFile = patch.currentFile;
          connection.lastSeenAt = new Date().toISOString();
        }
      }
      member.currentFile = patch.currentFile;
      return member;
    },
    getMember(roomId: string, memberId: string) {
      return rooms
        .get(roomId)
        ?.members.find((member) => member.id === memberId);
    },
    listRooms() {
      return [...rooms.values()];
    }
  };
}

export function applyTextDelta(
  text: Y.Text,
  previousContent: string,
  nextContent: string
) {
  let index = 0;

  for (const [operation, value] of diff(previousContent, nextContent)) {
    if (operation === diff.EQUAL) {
      index += value.length;
      continue;
    }
    if (operation === diff.DELETE) {
      text.delete(index, value.length);
      continue;
    }
    text.insert(index, value);
    index += value.length;
  }
}

export function createAgentRunStore(projectId: string, projectRoot: string) {
  const runsRoot = path.join(projectRoot, "agent-runs");
  const records = createRecordStore<AgentRun>({
    root: runsRoot,
    projectId,
    fileName: "run.json",
    recordKey: "run",
    invalidMessage: "Invalid Agent run file",
    missingMessage: "Agent run not found",
    validateRecord(value): value is AgentRun {
      if (!value || typeof value !== "object") return false;
      const run = value as Record<string, unknown>;
      return typeof run.id === "string" && typeof run.projectId === "string";
    }
  });

  return {
    runsRoot,
    create(input: Omit<AgentRun, "id" | "createdAt">, id = nanoid(12)) {
      return records.create({
        ...input,
        id,
        createdAt: new Date().toISOString()
      });
    },
    get: records.get,
    async list() {
      return (await records.list()).sort((left, right) =>
        right.createdAt.localeCompare(left.createdAt)
      );
    },
    update(runId: string, update: Partial<AgentRun>) {
      return records.update(runId, (current) => ({ ...current, ...update, id: current.id }));
    }
  };
}

