export function createChatStore(
  events: EventLog,
  options: { storagePath?: string } = {}
) {
  let messages: ChatMessage[] = [];
  let operations: Promise<void> | undefined;
  const listeners = new Set<(message: ChatMessage) => void>();

  function ensureLoaded() {
    operations ??= loadMessages(options.storagePath).then((loaded) => {
      messages = loaded;
    });
    return operations;
  }

  return {
    async createMessage(input: CreateChatMessageInput) {
      let created: ChatMessage | undefined;
      const creation = ensureLoaded().then(async () => {
        const message: ChatMessage = {
          sequence: (messages.at(-1)?.sequence ?? 0) + 1,
          id: nanoid(10),
          timestamp: new Date().toISOString(),
          roomId: input.roomId,
          authorId: input.authorId,
          authorName: input.authorName,
          authorRole: input.authorRole,
          agentSessionId: input.agentSessionId,
          runId: input.runId,
          mentions: input.mentions,
          kind: input.kind ?? "member",
          text: String(redactSensitive(input.text))
        };
        const nextMessages = [...messages, message];
        await saveMessages(options.storagePath, nextMessages);
        messages = nextMessages;
        events.append({
          type: "chat_message_created",
          roomId: message.roomId,
          memberId: message.authorId,
          payload: {
            messageId: message.id,
            authorName: message.authorName,
            ...(message.authorRole ? { authorRole: message.authorRole } : {}),
            text: message.text
          }
        });
        created = message;
        for (const listener of listeners) listener(message);
      });
      operations = creation;
      await creation;
      if (!created) throw new Error("Chat message was not created");
      return created;
    },
    async listMessages(roomId: string) {
      await ensureLoaded();
      return messages.map((message) => ({ ...message, roomId }));
    },
    async updateMessage(messageId: string, update: Partial<Pick<ChatMessage, "mentions" | "agentSessionId" | "runId">>) {
      let updated: ChatMessage | undefined;
      const operation = ensureLoaded().then(async () => {
        const index = messages.findIndex((message) => message.id === messageId);
        if (index < 0) throw new Error("Chat message not found");
        const current = messages[index];
        if (!current) throw new Error("Chat message not found");
        const message: ChatMessage = { ...current, ...update };
        const nextMessages = [...messages];
        nextMessages[index] = message;
        await saveMessages(options.storagePath, nextMessages);
        messages = nextMessages;
        updated = message;
        for (const listener of listeners) listener(message);
      });
      operations = operation;
      await operation;
      if (!updated) throw new Error("Chat message was not updated");
      return updated;
    },
    onMessage(listener: (message: ChatMessage) => void) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    async awaitIdle() {
      await ensureLoaded();
    }
  };
}

export function loadConfig(
  env: NodeJS.ProcessEnv = process.env,
  repositoryRoot = defaultRepositoryRoot
): ServerConfig {
  const port = Number(env.PORT ?? 4000);
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }

  const configuredDataDir = env.SIMPLERCP_DATA_DIR?.trim() || undefined;
  if (configuredDataDir && !path.isAbsolute(configuredDataDir)) {
    throw new Error("SIMPLERCP_DATA_DIR must be an absolute path");
  }

  const publicOrigin = env.SIMPLERCP_PUBLIC_URL ?? "http://127.0.0.1:5173";
  const publicUrl = new URL(publicOrigin);
  if (!["http:", "https:"].includes(publicUrl.protocol)) {
    throw new Error("SIMPLERCP_PUBLIC_URL must use http or https");
  }

  const agentBaseUrl = new URL(
    env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com/v1"
  );
  if (!["http:", "https:"].includes(agentBaseUrl.protocol)) {
    throw new Error("DEEPSEEK_BASE_URL must use http or https");
  }
  const agentModel = env.DEEPSEEK_MODEL?.trim() || "deepseek-chat";
  const openCodePort = Number(env.SIMPLERCP_OPENCODE_PORT ?? 4096);
  if (!Number.isInteger(openCodePort) || openCodePort < 1 || openCodePort > 65_535) {
    throw new Error("SIMPLERCP_OPENCODE_PORT must be an integer between 1 and 65535");
  }
  const runTimeoutMs = Number(env.SIMPLERCP_AGENT_RUN_TIMEOUT_MS ?? 600_000);
  if (!Number.isInteger(runTimeoutMs) || runTimeoutMs < 1) {
    throw new Error("SIMPLERCP_AGENT_RUN_TIMEOUT_MS must be a positive integer");
  }
  const terminalEnabled = readBoolean(
    env.SIMPLERCP_TERMINAL_ENABLED,
    "SIMPLERCP_TERMINAL_ENABLED",
    true
  );
  const fakeAgentRuntime = readBoolean(
    env.SIMPLERCP_FAKE_AGENT_RUNTIME,
    "SIMPLERCP_FAKE_AGENT_RUNTIME",
    false
  );
  const importRoots = !env.SIMPLERCP_IMPORT_ROOTS?.trim()
    ? undefined
    : env.SIMPLERCP_IMPORT_ROOTS.split(",").map((value) => value.trim()).filter(Boolean);
  if (importRoots?.some((root) => !path.isAbsolute(root))) throw new Error("SIMPLERCP_IMPORT_ROOTS must contain absolute paths");
  const dataDir = configuredDataDir ?? path.resolve(repositoryRoot, ".simplercp-data");
  const workspacesDir = env.SIMPLERCP_WORKSPACES_DIR?.trim() || path.join(dataDir, "workspaces");
  if (!path.isAbsolute(workspacesDir)) throw new Error("SIMPLERCP_WORKSPACES_DIR must be an absolute path");

  const config: ServerConfig = {
    port,
    host: env.SIMPLERCP_HOST ?? "127.0.0.1",
    publicOrigin: publicUrl.origin,
    dataDir,
    workspacesDir,
    importRoots,
    demoProjectRoot: path.resolve(repositoryRoot, "demo/workspace"),
    terminalEnabled,
    fakeAgentRuntime,
    agent: {
      apiKey: env.DEEPSEEK_API_KEY?.trim() || undefined,
      baseUrl: agentBaseUrl.toString().replace(/\/$/, ""),
      model: agentModel,
      openCodePort,
      runTimeoutMs
    }
  };
  return config;
}

export async function createProjectRegistry({
  dataDir,
  workspacesDir,
  importRoots,
  demoProjectRoot
}: {
  dataDir: string;
  workspacesDir?: string;
  importRoots?: string[];
  demoProjectRoot: string;
}) {
  const projectsDir = path.join(dataDir, "projects");
  const workspacesRoot = workspacesDir ?? path.join(dataDir, "workspaces");
  const registryPath = path.join(dataDir, "registry.json");
  await fs.mkdir(projectsDir, { recursive: true, mode: 0o700 });
  await fs.mkdir(workspacesRoot, { recursive: true, mode: 0o700 });

  let registry = await loadRegistry(registryPath);
  registry = await migrateLegacyProjects(registry, { projectsDir, workspacesDir: workspacesRoot, dataDir, registryPath });
  if (!registry.projects.some((project) => project.id === "demo")) {
    const project = await createDemoProject({ projectsDir, workspacesDir: workspacesRoot, demoProjectRoot });
    registry = { ...registry, projects: [...registry.projects, project] };
    await saveRegistry(registryPath, registry);
  }

  return {
    listProjectsSync() {
      return [...registry.projects];
    },
    async listProjects() {
      const missingProjectIds = new Set<string>();
      let recreatedDemo: ProjectRecord | undefined;
      for (const project of registry.projects) {
        if (await pathExists(project.workspacePath)) continue;
        if (project.id === "demo") {
          recreatedDemo = await createDemoProject({ projectsDir, workspacesDir: workspacesRoot, demoProjectRoot });
        } else {
          missingProjectIds.add(project.id);
        }
      }
      if (missingProjectIds.size > 0 || recreatedDemo) {
        registry = {
          ...registry,
          projects: registry.projects.flatMap((project) => {
            if (missingProjectIds.has(project.id)) return [];
            if (project.id === "demo" && recreatedDemo) return [recreatedDemo];
            return [project];
          })
        };
        await saveRegistry(registryPath, registry);
      }
      return [...registry.projects].sort((left, right) =>
        right.lastOpenedAt.localeCompare(left.lastOpenedAt)
      );
    },
    getProject(projectId: string) {
      return registry.projects.find((project) => project.id === projectId);
    },
    async createBlankProject(name: string) {
      const normalizedName = validateProjectName(name, registry.projects);
      const id = nanoid(12);
      const projectDir = path.join(projectsDir, id);
      const workspacePath = path.join(workspacesRoot, id);
      await fs.mkdir(workspacePath, { recursive: true, mode: 0o700 });
      const timestamp = new Date().toISOString();
      const project: ProjectRecord = {
        id,
        name: normalizedName,
        source: "blank",
        workspacePath,
        metadataPath: projectDir,
        createdAt: timestamp,
        lastOpenedAt: timestamp
      };
      await writeProjectMetadata(projectDir, project);
      registry = { ...registry, projects: [...registry.projects, project] };
      await saveRegistry(registryPath, registry);
      return project;
    },
    async importDirectory(name: string, sourcePath: string) {
      const normalizedName = validateProjectName(name, registry.projects);
      if (!path.isAbsolute(sourcePath)) {
        throw new Error("Existing project path must be absolute");
      }
      const realSource = await fs.realpath(sourcePath);
      if (importRoots) {
        const allowed = (await Promise.all(importRoots.map((root) => fs.realpath(root)))).some((root) => realSource === root || realSource.startsWith(`${root}${path.sep}`));
        if (!allowed) throw new Error("Directory import path is outside SIMPLERCP_IMPORT_ROOTS");
      }
      const sourceStat = await fs.stat(realSource);
      if (!sourceStat.isDirectory()) {
        throw new Error("Existing project path must be a directory");
      }

      const id = nanoid(12);
      const projectDir = path.join(projectsDir, id);
      const workspacePath = path.join(workspacesRoot, id);
      await fs.mkdir(projectDir, { recursive: true, mode: 0o700 });
      try {
        await fs.cp(realSource, workspacePath, {
          recursive: true,
          filter(candidatePath) {
            const relativePath = path.relative(realSource, candidatePath);
            return !relativePath || !isIgnoredPath(relativePath);
          }
        });
        const timestamp = new Date().toISOString();
        const project: ProjectRecord = {
          id,
          name: normalizedName,
          source: "directory",
          workspacePath,
          metadataPath: projectDir,
          createdAt: timestamp,
          lastOpenedAt: timestamp
        };
        await writeProjectMetadata(projectDir, project);
        registry = { ...registry, projects: [...registry.projects, project] };
        await saveRegistry(registryPath, registry);
        return project;
      } catch (error) {
        await fs.rm(projectDir, { recursive: true, force: true });
        throw error;
      }
    },
    async importZip(name: string, archive: Buffer) {
      const normalizedName = validateProjectName(name, registry.projects);
      const id = nanoid(12);
      const projectDir = path.join(projectsDir, id);
      const workspacePath = path.join(workspacesRoot, id);
      await fs.mkdir(projectDir, { recursive: true, mode: 0o700 });
      try {
        const { filteredEntries } = await extractZipArchive({
          archive,
          destination: workspacePath
        });
        const timestamp = new Date().toISOString();
        const project: ProjectRecord = {
          id,
          name: normalizedName,
          source: "zip",
          workspacePath,
          metadataPath: projectDir,
          createdAt: timestamp,
          lastOpenedAt: timestamp
        };
        await writeProjectMetadata(projectDir, project);
        registry = { ...registry, projects: [...registry.projects, project] };
        await saveRegistry(registryPath, registry);
        return { project, filteredEntries };
      } catch (error) {
        await fs.rm(projectDir, { recursive: true, force: true });
        throw error;
      }
    },
    async markOpened(projectId: string) {
      const project = registry.projects.find(
        (candidate) => candidate.id === projectId
      );
      if (!project) throw new Error("Project not found");
      if (!(await pathExists(project.workspacePath))) {
        registry = {
          ...registry,
          projects: registry.projects.filter(
            (candidate) => candidate.id !== projectId
          )
        };
        await saveRegistry(registryPath, registry);
        throw new Error("Project not found");
      }
      project.lastOpenedAt = new Date().toISOString();
      await saveRegistry(registryPath, registry);
      return project;
    },
    async deleteProject(projectId: string) {
      if (projectId === "demo") {
        throw new Error("Demo project cannot be deleted");
      }
      const project = registry.projects.find(
        (candidate) => candidate.id === projectId
      );
      if (!project) throw new Error("Project not found");
      const projectDir = resolveProjectDir(projectsDir, project.id);
      await fs.rm(projectDir, { recursive: true, force: true });
      await fs.rm(project.workspacePath, { recursive: true, force: true });
      registry = {
        ...registry,
        projects: registry.projects.filter(
          (candidate) => candidate.id !== projectId
        )
      };
      await saveRegistry(registryPath, registry);
      return project;
    }
  };
}

export function createEventLog(storagePath?: string) {
  const events: EventRecord[] = [];
  let operations = Promise.resolve();
  const loading = storagePath ? loadEvents(storagePath, events) : Promise.resolve();

  function enqueue(operation: () => Promise<void>) {
    const result = operations.then(operation);
    operations = result.then(() => undefined, () => undefined);
  }

  return {
    append(input: EventInput) {
      const event: EventRecord = redactSensitive({
        id: nanoid(),
        timestamp: new Date().toISOString(),
        ...input
      }) as EventRecord;
      events.push(event);
      if (storagePath && durableEventTypes.has(event.type)) {
        enqueue(async () => {
          await loading;
          await writeJsonFileAtomically(storagePath, {
            version: 1,
            events: events.filter((candidate) => durableEventTypes.has(candidate.type))
          } satisfies EventFile);
        });
      }
      return event;
    },
    list() {
      return [...events];
    },
    async awaitIdle() {
      await loading;
      await operations;
    }
  };
}

export function requirePermission(request: Request, response: Response, action: Action, resource?: { projectId?: string; ownerMemberId?: string }) {
  const identity = requireIdentity(request, response);
  if (!identity) return undefined;
  if (!can(identity, action, resource)) {
    response.status(403).json({ error: "Permission denied" });
    return undefined;
  }
  return identity;
}

export function createMemberStore(options: { projects: () => ProjectRecord[] }) {
  const cache = new Map<string, MemberFile>();
  const loading = new Map<string, Promise<MemberFile>>();
  let operations = Promise.resolve();

  function enqueue<T>(operation: () => Promise<T>) {
    const result = operations.then(operation);
    operations = result.then(() => undefined, () => undefined);
    return result;
  }

  function findProject(projectId: string) {
    const project = options.projects().find((candidate) => candidate.id === projectId);
    if (!project) throw new Error("Project not found");
    return project;
  }

  function projectDataPath(project: ProjectRecord) {
    return getProjectMetadataPath(project);
  }

  async function load(projectId: string) {
    const cached = cache.get(projectId);
    if (cached) return cached;
    const pending = loading.get(projectId);
    if (pending) return pending;
    const operation = loadFile(projectId);
    loading.set(projectId, operation);
    try { return await operation; }
    finally { loading.delete(projectId); }
  }

  async function loadFile(projectId: string) {
    const project = findProject(projectId);
    const stored = await readJsonFile<MemberFile>(path.join(projectDataPath(project), "members.json"));
    if (stored && (stored.version !== 1 || !Array.isArray(stored.members))) throw new Error("Invalid member file");
    const legacy = stored === undefined
      ? await readJsonFile<{ version: 1; participants: Array<{ id: string; displayName: string; profileRole?: string; createdAt: string; updatedAt: string }> }>(path.join(projectDataPath(project), "participants.json"))
      : undefined;
    const records = stored?.members ?? legacy?.participants.map((member) => ({
      memberId: member.id, projectId, displayName: member.displayName, role: member.profileRole ?? "", createdAt: member.createdAt, updatedAt: member.updatedAt
    })) ?? [];
    const file: MemberFile = { version: 1, members: records.map((member) => ({
      memberId: member.memberId, projectId: member.projectId, displayName: member.displayName,
      role: member.role ?? "", createdAt: member.createdAt, updatedAt: member.updatedAt ?? member.createdAt
    })) };
    if (file.members.some((member) => !member.memberId || member.projectId !== projectId || typeof member.displayName !== "string" || typeof member.role !== "string")) throw new Error("Invalid member record");
    if (legacy || (stored && JSON.stringify(stored) !== JSON.stringify(file))) await save(projectId, file);
    cache.set(projectId, file);
    return file;
  }

  async function save(projectId: string, file: MemberFile) {
    const project = findProject(projectId);
    await writeJsonFileAtomically(path.join(projectDataPath(project), "members.json"), file, 0o600);
    cache.set(projectId, file);
  }

  return {
    async join(projectId: string, input: { memberId?: string; displayName: string; role?: string }) {
      return enqueue(async () => {
        const displayName = input.displayName.trim();
        if (!displayName) throw new Error("name is required");
        const file = await load(projectId);
        const now = new Date().toISOString();
        if (input.memberId) {
          const index = file.members.findIndex((member) => member.memberId === input.memberId);
          if (index >= 0) {
            const current = file.members[index]!;
            const member = { ...current, displayName, role: input.role?.trim() ?? current.role, updatedAt: now };
            file.members[index] = member;
            await save(projectId, file);
            return member;
          }
        }
        const member: MemberRecord = {
          memberId: crypto.randomUUID(),
          projectId,
          displayName,
          role: input.role?.trim() ?? "",
          createdAt: now,
          updatedAt: now
        };
        await save(projectId, { version: 1, members: [...file.members, member] });
        return member;
      });
    },
    async getMember(projectId: string, memberId: string) {
      return (await load(projectId)).members.find((member) => member.memberId === memberId);
    },
    async listMembers(projectId: string) {
      return (await load(projectId)).members.map((member) => ({ ...member }));
    },
    async resolveIdentity(projectId: string, memberId: string) {
      return (await load(projectId)).members.find((member) => member.memberId === memberId);
    },
    async findIdentity(memberId: string) {
      for (const project of options.projects()) {
        const member = (await load(project.id)).members.find((candidate) => candidate.memberId === memberId);
        if (member) return member;
      }
    }
  };
}

