export function createRoomStore(events: EventLog) {
  const rooms = new Map<string, RoomState>();

  return {
    createRoom(workspaceRoot: string, workspaceName = path.basename(workspaceRoot)) {
      const room: RoomState = {
        id: nanoid(10),
        workspaceName,
        members: [],
        connections: []
      };
      rooms.set(room.id, room);
      events.append({
        type: "room_created",
        roomId: room.id,
        payload: { workspaceName: room.workspaceName }
      });
      return room;
    },
    getRoom(roomId: string) {
      return rooms.get(roomId);
    },
    joinRoom(roomId: string, input: JoinRoomInput) {
      const room = rooms.get(roomId);
      if (!room) {
        throw new Error("Room not found");
      }

      const normalized = normalizeJoinInput(input);
      const now = new Date().toISOString();
      const existing = findExistingMember(room.members, normalized);
      if (existing) {
        existing.name = normalized.name;
        existing.participantId = normalized.participantId;
        existing.profileRole = normalized.profileRole;
        upsertConnection(room, {
          id: normalized.connectionId,
          participantId: existing.participantId,
          roomId,
          online: true,
          lastSeenAt: now
        });
        syncMemberFromConnections(room, existing, now);
        refreshDisplayNames(room);
        events.append({
          type: "member_rejoined",
          roomId,
          memberId: existing.id,
          payload: {
            name: existing.name,
            participantId: existing.participantId,
            connectionId: normalized.connectionId,
            connectionCount: existing.connectionCount
          }
        });
        return existing;
      }

      const member: RoomMember = {
        id: input.memberId ?? nanoid(10),
        participantId: normalized.participantId,
        name: normalized.name,
        displayName: normalized.name,
        online: true,
        lastSeenAt: now,
        connectionCount: 1,
        profileRole: normalized.profileRole
      };
      room.members.push(member);
      upsertConnection(room, {
        id: normalized.connectionId,
        participantId: member.participantId,
        roomId,
        online: true,
        lastSeenAt: now
      });
      refreshDisplayNames(room);
      events.append({
        type: "member_joined",
        roomId,
        memberId: member.id,
        payload: {
          name: member.name,
          participantId: member.participantId,
          connectionId: normalized.connectionId
        }
      });
      return member;
    },
    markOnline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = true;
      member.lastSeenAt = now.toISOString();
      if (!wasOnline) {
        events.append({
          type: "member_online",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOnline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = true;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (!wasOnline && member.online) {
        events.append({
          type: "member_online",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    markOffline(roomId: string, memberId: string, now = new Date()) {
      const member = findMember(rooms, roomId, memberId);
      const wasOnline = member.online;
      member.online = false;
      member.lastSeenAt = now.toISOString();
      if (wasOnline) {
        events.append({
          type: "member_offline",
          roomId,
          memberId,
          payload: { name: member.displayName, lastSeenAt: member.lastSeenAt }
        });
      }
      return member;
    },
    markConnectionOffline(roomId: string, connectionId: string, now = new Date()) {
      const room = findRoom(rooms, roomId);
      const connection = room.connections.find(
        (candidate) => candidate.id === connectionId
      );
      if (!connection) {
        throw new Error("Connection not found");
      }
      const member = room.members.find(
        (candidate) => candidate.participantId === connection.participantId
      );
      if (!member) {
        throw new Error("Member not found");
      }
      const wasOnline = member.online;
      connection.online = false;
      connection.lastSeenAt = now.toISOString();
      syncMemberFromConnections(room, member, now.toISOString());
      if (wasOnline && !member.online) {
        events.append({
          type: "member_offline",
          roomId,
          memberId: member.id,
          payload: {
            name: member.displayName,
            connectionId,
            lastSeenAt: member.lastSeenAt
          }
        });
      }
      return member;
    },
    cleanupStaleMembers(roomId: string, now = new Date(), ttlMs = 120_000) {
      const room = findRoom(rooms, roomId);

      const before = room.members.length;
      room.connections = room.connections.filter((connection) => {
        if (connection.online) return true;
        return now.getTime() - new Date(connection.lastSeenAt).getTime() <= ttlMs;
      });
      for (const member of room.members) {
        syncMemberFromConnections(room, member, member.lastSeenAt);
      }
      room.members = room.members.filter((member) => {
        if (member.online) return true;
        return now.getTime() - new Date(member.lastSeenAt).getTime() <= ttlMs;
      });

      if (room.members.length !== before) {
        events.append({
          type: "member_removed",
          roomId,
          payload: { removed: before - room.members.length }
        });
      }

      return room.members;
    },
    updatePresence(
      roomId: string,
      memberId: string,
      patch: Pick<RoomMember, "currentFile"> & { connectionId?: string }
    ) {
      const room = findRoom(rooms, roomId);
      const member = room.members.find(
        (candidate) => candidate.id === memberId
      );
      if (!member) {
        throw new Error("Member not found");
      }

      if (patch.connectionId) {
        const connection = room.connections.find(
          (candidate) => candidate.id === patch.connectionId
        );
        if (connection) {
          connection.currentFile = patch.currentFile;
          connection.lastSeenAt = new Date().toISOString();
        }
      }
      member.currentFile = patch.currentFile;
      return member;
    },
    getMember(roomId: string, memberId: string) {
      return rooms
        .get(roomId)
        ?.members.find((member) => member.id === memberId);
    },
    listRooms() {
      return [...rooms.values()];
    }
  };
}

export function agentEnv(env: NodeJS.ProcessEnv = process.env) {
  return buildEnvironment(env, ["DEEPSEEK_API_KEY", "DEEPSEEK_BASE_URL", "DEEPSEEK_MODEL", ...(env.SIMPLERCP_AGENT_ENV_ALLOW ?? "").split(",").map((name) => name.trim())], true);
}

export function loadConfig(
  env: NodeJS.ProcessEnv = process.env,
  repositoryRoot = defaultRepositoryRoot
): ServerConfig {
  const port = Number(env.PORT ?? 4000);
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }

  const configuredDataDir = env.SIMPLERCP_DATA_DIR?.trim() || undefined;
  if (configuredDataDir && !path.isAbsolute(configuredDataDir)) {
    throw new Error("SIMPLERCP_DATA_DIR must be an absolute path");
  }

  const publicOrigin = env.SIMPLERCP_PUBLIC_URL ?? "http://127.0.0.1:5173";
  const publicUrl = new URL(publicOrigin);
  if (!["http:", "https:"].includes(publicUrl.protocol)) {
    throw new Error("SIMPLERCP_PUBLIC_URL must use http or https");
  }

  const agentBaseUrl = new URL(
    env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com/v1"
  );
  if (!["http:", "https:"].includes(agentBaseUrl.protocol)) {
    throw new Error("DEEPSEEK_BASE_URL must use http or https");
  }
  const agentModel = env.DEEPSEEK_MODEL?.trim() || "deepseek-chat";
  const openCodePort = Number(env.SIMPLERCP_OPENCODE_PORT ?? 4096);
  if (!Number.isInteger(openCodePort) || openCodePort < 1 || openCodePort > 65_535) {
    throw new Error("SIMPLERCP_OPENCODE_PORT must be an integer between 1 and 65535");
  }
  const runTimeoutMs = Number(env.SIMPLERCP_AGENT_RUN_TIMEOUT_MS ?? 600_000);
  if (!Number.isInteger(runTimeoutMs) || runTimeoutMs < 1) {
    throw new Error("SIMPLERCP_AGENT_RUN_TIMEOUT_MS must be a positive integer");
  }
  const terminalEnabled = readBoolean(
    env.SIMPLERCP_TERMINAL_ENABLED,
    "SIMPLERCP_TERMINAL_ENABLED",
    true
  );
  const fakeAgentRuntime = readBoolean(
    env.SIMPLERCP_FAKE_AGENT_RUNTIME,
    "SIMPLERCP_FAKE_AGENT_RUNTIME",
    false
  );
  const importRoots = !env.SIMPLERCP_IMPORT_ROOTS?.trim()
    ? undefined
    : env.SIMPLERCP_IMPORT_ROOTS.split(",").map((value) => value.trim()).filter(Boolean);
  if (importRoots?.some((root) => !path.isAbsolute(root))) throw new Error("SIMPLERCP_IMPORT_ROOTS must contain absolute paths");
  const dataDir = configuredDataDir ?? path.resolve(repositoryRoot, ".simplercp-data");
  const workspacesDir = env.SIMPLERCP_WORKSPACES_DIR?.trim() || path.join(dataDir, "workspaces");
  if (!path.isAbsolute(workspacesDir)) throw new Error("SIMPLERCP_WORKSPACES_DIR must be an absolute path");

  const config: ServerConfig = {
    port,
    host: env.SIMPLERCP_HOST ?? "127.0.0.1",
    publicOrigin: publicUrl.origin,
    dataDir,
    workspacesDir,
    importRoots,
    demoProjectRoot: path.resolve(repositoryRoot, "demo/workspace"),
    terminalEnabled,
    fakeAgentRuntime,
    agent: {
      apiKey: env.DEEPSEEK_API_KEY?.trim() || undefined,
      baseUrl: agentBaseUrl.toString().replace(/\/$/, ""),
      model: agentModel,
      openCodePort,
      runTimeoutMs
    }
  };
  return config;
}

